INSERT INTO `Job` (`id`, `priority`, `name`, `link`, `description`, `archive`, `imageId`, `lang`, `created`) VALUES
('12', 2, 'Application for learning foreign languages', 'https://github.com/kolserdav/ana', 'An open-source app that uses AI (Libre Translate) to help the user create sentences in the target language. It also allows you to save them and listen to them using speech synthesis. Before it was shut down, it was available on FDroid.', 0, 2, 'en', '2025-03-26 07:27:36.852'),
('13', 3, 'Online call to add to the site', 'https://github.com/kolserdav/sfu-react', 'Developed a React component and open-source server that allows you to add multi-participant video call functionality to your website. Based on WebRTC technology.', 0, 3, 'en', '2025-03-26 07:40:34.995'),
('16', 1, 'Container Hosting', 'https://conhos.ru', 'A cloud service for hosting Docker containers has been developed and supported.', 0, 6, 'en', '2025-03-26 08:17:02.167'),
('17', 7, 'Automation of business processes', 'https://github.com/kolserdav/automatic', 'Made a website for self-promotion. At the moment, the source code of the site is open.', 0, 7, 'en', '2025-03-26 08:30:11.101'),
('2', 2, 'Приложение для изучения иностранных языков', 'https://github.com/kolserdav/ana', 'Приложение с открытым исходным кодом, которое на основе ИИ (Libre Translate) помогает пользователю составлять предложения на изучаемом языке. А также позволяет сохранять их и прослушивать с помощью синтеза речи. До того как было свернуто, было доступно на FDroid.', 0, 2, 'ru', '2025-03-26 07:27:36.852'),
('3', 3, 'Звонилка на сайт', 'https://github.com/kolserdav/sfu-react', 'Разработал React компонент и сервер с открытым исходным кодом, который позволяет добавлять на сайт функционал видеозвонка с несколькими участниками. На основе технологии WebRTC.', 0, 3, 'ru', '2025-03-26 07:40:34.995'),
('6', 1, 'Контейнерный Хостинг', 'https://conhos.ru', 'Разработан и поддерживается облачный сервис для размещения Docker контейнеров.', 0, 6, 'ru', '2025-03-26 08:17:02.167'),
('7', 7, 'Автоматизация бизнес процессов', 'https://github.com/kolserdav/automatic', 'Делал сайт для саморекламы. В данный момент, исходный код сайта открыт.', 0, 7, 'ru', '2025-03-26 08:30:11.101');
INSERT INTO `PageIndex` (`id`, `metaTitle`, `metaDescription`, `metaKeywords`, `headerTitle`, `headerSubtitle`, `headerDescription`, `aboutTitle`, `aboutSubtitle`, `personalTitle`, `personalDescription`, `techTitle`, `techDescription`, `sliderTitle`, `sliderDescription`, `cloudTitle`, `cloudContent`, `lang`, `created`) VALUES
(1, 'Портфолио программиста', 'Демонстрация опыта работы разработчика ПО Кольмиллер Сергея', 'node, фрилансер', 'Портфолио программиста', 'Демонстрация работ разработчика ПО Кольмиллер Сергея', 'Сложное состоит из простого, а великое из мáлого', 'Обо мне', 'Биография в ИТ (коротко)', 'Кольмиллер Сергей', 'В ИТ с 2010 года, создавал сайты на CMS, совмещая с основной работой.\r\nПрограммировать начал с 2017 года, после того как закончил курсы по основам программирования. С того времени ничем, кроме разработки не занимался.', 'Навыки в технологиях', 'Это далеко не полный список моих навыков. Здесь указаны только те, с которыми работаю чаще всего.', 'Работы', 'Это не полный список проектов в которых я принимал участие. Показаны только самые интересные и те в разработке которых я играл ключевую роль.', 'Облачный сервис', 'Для размещения приложений в сети, я использовал множество разных сервисов. Но теперь я создал свой сервис, в котором размещаю все свои проекты, в том числе и этот сайт. Контейнерый Хостинг это удобный и недорогой хостинг на основе Docker контейнеров.', 'ru', '2025-03-24 03:57:49.239'),
(2, 'Programmer portfolio', 'Demonstration of the work experience of software developer Kolmiller Sergei', 'node, freelancer', 'Programmer portfolio', 'Demonstration of the works of software developer Kolmiller Sergei', 'The complex consists of the simple, and the great of the small', 'About me', 'Biography in IT (short)', 'Kolmiller Sergei', 'In IT since 2010, created websites on CMS, combining it with his main job.\r\nStarted programming in 2017, after completing courses on the basics of programming. Since then, I have not done anything except development.', 'Skills in technology', 'This is far from a complete list of my skills. Here are listed only those that I work with most often.', 'Jobs', 'This is not a complete list of projects I took part in. Only the most interesting ones are shown, and those in the development of which I played a key role.', 'Cloud service', 'To host applications on the network, I used many different services. But now I have created my own service, where I host all my projects, including this site. Container Hosting is a convenient and inexpensive hosting based on Docker containers.', 'en', '2025-03-24 03:57:49.239');
